import { createRequire } from "node:module";
import express, { type Router } from "express";

// Vercel compiles this file as ESM but does not bundle the backend sources.
// Load the compiled CommonJS backend (generated by `npm run build:backend`).
const loadModule = createRequire(import.meta.url);
const { router } = loadModule("../backend/dist/app.js") as { router: Router };

const app = express();

app.use(express.json({ limit: "4mb" }));

// Vercel rewrites /api/* to /api/index?__path=* so the function path stays
// valid. Restore the original path before handing the request to Express.
app.use((req, _res, next) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const rewrittenPath = url.searchParams.get("__path");

  if (rewrittenPath !== null) {
    req.url = rewrittenPath ? `/api/${rewrittenPath}` : "/api/";
  }

  next();
});

app.use("/api", router);

export default app;
